$phones$, E'\r?\n+') AS value
),
normalized AS (
    SELECT
        CASE
            WHEN phone_raw ~ '^[0-9]{10}$' THEN '+7' || phone_raw
            WHEN phone_raw ~ '^[0-9]{11}$' THEN '+' || phone_raw
            ELSE NULL
        END AS phone
    FROM imported
),
deduped AS (
    SELECT DISTINCT phone
    FROM normalized
    WHERE phone IS NOT NULL
),
new_clients AS (
    SELECT phone
    FROM deduped d
    WHERE NOT EXISTS (
        SELECT 1
        FROM clients c
        WHERE regexp_replace(c.phone, '[^0-9]', '', 'g') = regexp_replace(d.phone, '[^0-9]', '', 'g')
    )
)
INSERT INTO clients (first_name, last_name, phone, status, source)
SELECT
    'Импорт',
    'Клиент ' || LPAD(ROW_NUMBER() OVER (ORDER BY phone)::text, 4, '0'),
    phone,
    'NEW',
    'base.xlsx'
FROM new_clients;
